const rows = $input.all().map(r => r.json);
const cfg = $('Cấu Hình').first().json;

function num(v) {
  const n = Number(String(v ?? '').replace(/[^0-9.-]/g, ''));
  return Number.isFinite(n) ? n : 0;
}
function truthy(v) { return String(v).toLowerCase() === 'true'; }

const ym = new Date().toISOString().slice(0, 7);
const ymParts = ym.split('-').map(Number);
const prevYm = `${ymParts[1] === 1 ? ymParts[0] - 1 : ymParts[0]}-${String(ymParts[1] === 1 ? 12 : ymParts[1] - 1).padStart(2, '0')}`;

function monthRows(m) { return rows.filter(r => String(r['Year Month'] || '') === m); }

function agg(rs) {
  const spend = rs.reduce((s, r) => s + num(r['Total Amount VND']), 0);
  const count = rs.length;
  const needReview = rs.filter(r => String(r['Status']) === 'manual_review' || truthy(r['Needs Manual Review'])).length;
  const highValue = rs.filter(r => truthy(r['High Value'])).length;
  const failed = rs.filter(r => String(r['Status']) === 'ocr_failed').length;
  const byVendor = {};
  for (const r of rs) {
    const v = String(r['Vendor Canonical'] || r['Seller Name'] || '(không rõ)');
    byVendor[v] = (byVendor[v] || 0) + num(r['Total Amount VND']);
  }
  const top = Object.entries(byVendor).sort((a, b) => b[1] - a[1])[0];
  return { spend, count, avg: count ? Math.round(spend / count) : 0, needReview, highValue, failed,
           topVendor: top ? top[0] : '(không rõ)', topVendorSpend: top ? top[1] : 0 };
}

const cur = agg(monthRows(ym));
const prv = agg(monthRows(prevYm));
const spendDeltaPct = prv.spend > 0 ? Math.round(((cur.spend - prv.spend) / prv.spend) * 100) : null;
const anomalyThreshold = Number(cfg.anomaly_pct_threshold) || 30;
const isAnomaly = spendDeltaPct !== null && Math.abs(spendDeltaPct) >= anomalyThreshold;
const model = String(cfg.gemini_model || 'gemini-2.5-flash');

const prompt = `Bạn là Senior Data Analyst của phòng kế toán. Viết commentary 100-150 từ tiếng Việt cho dashboard chi tiêu hóa đơn.

DATA THÁNG ${ym}:
- Tổng chi (VND): ${cur.spend.toLocaleString('vi-VN')} (tháng trước ${prevYm}: ${prv.spend.toLocaleString('vi-VN')}${spendDeltaPct !== null ? `, thay đổi ${spendDeltaPct > 0 ? '+' : ''}${spendDeltaPct}%` : ''})
- Số hóa đơn: ${cur.count} | Giá trị trung bình: ${cur.avg.toLocaleString('vi-VN')} VND
- Nhà cung cấp chi nhiều nhất: ${cur.topVendor} (${cur.topVendorSpend.toLocaleString('vi-VN')} VND)
- Hóa đơn giá trị lớn: ${cur.highValue} | Cần kiểm tra lại: ${cur.needReview} | Lỗi OCR: ${cur.failed}

QUY TẮC VIẾT:
- Tone professional, không alarmist, không bịa insight.
- Mở đầu bằng con số quan trọng nhất + so sánh tháng trước.
- 1-2 nhận định đáng chú ý (vendor tập trung chi, chất lượng OCR, xu hướng chi tiêu).
- Kết: 1-2 hành động cụ thể cho kế toán/quản lý.
- Nếu mọi thứ bình thường thì nói ngắn gọn, đừng bịa "insight".
- KHÔNG markdown, KHÔNG emoji. Chỉ trả text thuần 100-150 từ.`;

return [{
  json: {
    metrics: {
      thang: ym, thang_truoc: prevYm,
      chi_thang_nay: cur.spend, chi_thang_truoc: prv.spend, delta_pct: spendDeltaPct,
      so_hoa_don: cur.count, gia_tri_tb: cur.avg,
      can_review: cur.needReview, hoa_don_lon: cur.highValue, loi_ocr: cur.failed,
      top_vendor: cur.topVendor, top_vendor_chi: cur.topVendorSpend
    },
    is_anomaly: isAnomaly,
    spend_delta_pct: spendDeltaPct,
    gemini_model: model,
    gemini_request: {
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      generationConfig: { temperature: 0.3, maxOutputTokens: 1024 }
    }
  }
}];

const resp = $input.first().json;
const kpi = $('Tính KPI & Bất Thường').first().json;
const m = kpi.metrics;

function esc(v) { return String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }

let commentary = (resp?.candidates?.[0]?.content?.parts?.[0]?.text || '').trim();
if (!commentary) {
  commentary = 'Không tạo được nhận định tự động (Gemini không trả nội dung). Vui lòng xem số liệu trực tiếp trên dashboard.';
}

const today = new Date().toISOString().slice(0, 10);
const now = new Date().toISOString();

const commentaryRow = {
  'Date': today,
  'Period': m.thang,
  'Commentary': commentary,
  'Total Spend VND': m.chi_thang_nay,
  'Invoice Count': m.so_hoa_don,
  'Avg Value VND': m.gia_tri_tb,
  'Delta vs Prev %': m.delta_pct,
  'Needs Review': m.can_review,
  'OCR Failed': m.loi_ocr,
  'Top Vendor': m.top_vendor,
  'Generated At': now
};

const out = { commentary, commentary_row: commentaryRow, is_anomaly: Boolean(kpi.is_anomaly) };

if (kpi.is_anomaly) {
  const delta = kpi.spend_delta_pct;
  const sign = delta > 0 ? 'tăng' : 'giảm';
  const severity = Math.abs(delta) >= 50 ? 'HIGH' : 'MEDIUM';
  out.anomaly_row = {
    'Date': today,
    'Period': m.thang,
    'Metric': 'Tổng chi tiêu tháng',
    'Value VND': m.chi_thang_nay,
    'Baseline VND': m.chi_thang_truoc,
    'Delta %': delta,
    'Severity': severity,
    'Note': `Chi tiêu tháng ${m.thang} ${sign} ${Math.abs(delta)}% so với ${m.thang_truoc}.`
  };
  out.telegram_message = `🚨 <b>CẢNH BÁO CHI TIÊU BẤT THƯỜNG</b>\n\n<b>Kỳ:</b> ${esc(m.thang)}\n<b>Tổng chi:</b> ${Number(m.chi_thang_nay).toLocaleString('vi-VN')} VND (${sign} ${Math.abs(delta)}% vs ${esc(m.thang_truoc)})\n<b>Số hóa đơn:</b> ${m.so_hoa_don}\n<b>Mức độ:</b> ${severity}\n\n${esc(commentary)}`;
}

return [{ json: out }];
